source("pre.R")
cat("--- zero rows\n")
x0 <- zutable(a = integer(), s = character(), f = double(), d = as.Date(character()), e = factor(character(), levels = c("u", "v")), t = as.POSIXct(character(), tz = "UTC"), b = logical())
qs <- list(quote(x0[a > 1]), quote(x0[select = .(a, z = a + 1L, s2 = concat(s, "x"), u = upper(s), n = nchar(s), k = substr(s, 1L, 2L), c = cast(a, string), ci = cast(s, int32), cd = cast(s, date), y = year(d), tr = date_trunc("month", t), lk = like(s, "a%"), i = ifelse(b, a, 0L), cs = case(b ~ 1, .default = 2), co = coalesce(f, 0), r = round(f, 2L), inn = a %in% 1:3, bt = between(f, 0, 1))]),
  quote(x0[select = .(n = .N, s = sum(f), m = mean(a), mn = min(s), mx = max(d), f = first(e), l = last(t), cd = count_distinct(s), an = any(b), al = all(b))]), quote(x0[by = s, select = .(n = .N, s2 = sum(f))]), quote(x0[by = .(s, e), select = .(mx = max(t)), having = mx > "2020-01-01"]),
  quote(x0[order = .(desc(s), a)]), quote(x0[distinct = TRUE]), quote(x0[limit = 0]), quote(x0[limit = 5]), quote(x0[select = .(.all, o = over(sum(f), by = s))]), quote(x0[select = .(lit = 1L, s)]), quote(x0[select = .(r = r(a + 1L, int32))]), quote(join(x0, x0, on = a, suffix = c("", "2"), how = "full")), quote(rbind(x0, x0)), quote(x0[1:2][a > 1]), quote(x0[, a := a + 1L]), quote(x0[b, s := "q", by = e]), quote(x0[select = .(k = 1L)][by = k, select = .(n = .N)]))
for (q in qs) { a <- tryCatch({ r <- eval(q); schema(r); paste(nrow(r), "rows:", paste(format(schema(r)), collapse = ", ")) }, error = function(e) paste("ERR", conditionMessage(e))); b <- ref(tryCatch({ r <- eval(q); schema(r); paste(nrow(r), "rows:", paste(format(schema(r)), collapse = ", ")) }, error = function(e) paste("ERR", conditionMessage(e)))); cat(if (identical(a, b)) "same" else "DIFF", "|", substr(deparse(q)[1], 1, 60), "\n   ", substr(a, 1, 300), "\n"); if (!identical(a, b)) cat("   ", b, "\n") }
r <- x0[select = .(n = .N, s = sum(f), mn = min(s), f = first(e), l = last(t))]; str(as.data.frame(r))
x1 <- zutable(a = 1L, s = "x"); print(x1[a > 5, .(lit = 1L, s)]); print(x1[select = .(lit = 1L)]); print(try_(x1[select = .(lit = c(1L, 2L))])); print(zutable(a = 1:3)[select = .(lit = "k", a)])
cat("--- timestamp units\n")
s <- schema(ts = timestamp("s", "UTC"), tm = timestamp("ms", "UTC"), tz0 = timestamp("us"))
p <- as.POSIXct(c(1.0, 2.5, 3.123), origin = "1970-01-01", tz = "UTC")
print(try_(as_zutable(data.frame(ts = p, tm = p, tz0 = p), s)))
v <- try_(as_zutable(data.frame(ts = round(p), tm = p, tz0 = p), s)); print(v)
print(try_(v[, ts := ts + 1])); try_(v$ts[2] <- v$ts[2] + 0.5); try_(v[, tm := cast("1970-01-01 00:00:00.0005", timestamp("ms", "UTC"))]); print(as.numeric(v$tm)); try_(v[, tm := "1970-01-01 00:00:00.0005"]); print(as.numeric(v$tm))
print(try_(v[select = .(c1 = ts < tm, c2 = ts == tz0)])); print(try_(v[select = .(c2 = tm == tz0)])); print(try_(v[ts > "1970-01-01 00:00:01.5"])); print(try_(schema(v[select = .(a = cast(tm, timestamp("s", "UTC")))]))); r <- try_(v[select = .(a = cast(tm, timestamp("s", "UTC")))]); print(as.numeric(r$a)); print(tryCatch({conform(r, schema(r)); "valid"}, error = function(e) conditionMessage(e)))
print(try_(schema(v[select = .(m = max(tm), d = date_trunc("day", ts), mi = min(tz0))]))); print(try_(v[select = .(x = cast(tz0, timestamp("us", "Asia/Tokyo")), y = cast(tz0, string), z = cast(ts, timestamp("us")))]))
z <- zutable(t = as.POSIXct("2020-06-01 12:00:00", tz = "Asia/Tokyo")); print(as.data.frame(z[select = .(s = cast(t, string), d = cast(t, date), h = date_trunc("hour", t), y = year(t), dd = day(t), nz = cast(cast(t, timestamp("us")), string), c = t == "2020-06-01 12:00:00", lit = t > as.POSIXct("2020-06-01 02:59:59", tz = "UTC"))]))
z2 <- zutable(t = as.POSIXct("2020-06-01 23:30:00", tz = "Asia/Tokyo"), d = as.Date("2020-06-01")); print(try_(as.data.frame(z2[select = .(c = cast(t, date) == d, e = cast(d, timestamp("us", "Asia/Tokyo")) < t)]))); print(try_(z2[t > d])); print(try_(z2[t > "2020-06-01"]))
cat("--- conform/as_zutable\n")
df <- data.frame(a = 1:2, b = c("x", "y"))
print(try_(conform(df, schema(a = int32)))); print(try_(conform(df, schema(b = string, a = int32)))); print(try_(conform(df, schema(a = float64, b = string)))); print(try_(conform(df, schema(a = int32, b = enum(c("x", "y")))))); print(try_(conform(df, "a"))); print(try_(conform(list(a = 1), schema(a = float64)))); print(try_(conform(as_zutable(df), schema(a = not_null(int32), b = string, .metadata = c(k = "v"))))); print(metadata(conform(as_zutable(df), schema(a = not_null(int32), b = string, .metadata = c(k = "v")))))
print(try_(as_zutable(df, schema = "x"))); print(try_(as_zutable(list(a = 1:2, b = "x"), schema(a = int32, b = string)))); print(try_(as_zutable(df, schema(df)))); print(identical(as_zutable(as_zutable(df)), as_zutable(df)))
dn <- data.frame(a = 1:2); attr(dn$a, "label") <- "my label"; zz <- as_zutable(dn); print(attributes(zz$a)); print(attributes(zz[a > 0]$a)); print(attributes(zz[select = .(a)]$a)); print(attributes(zz[order = a]$a)); print(attributes(rbind(zz, zz)$a))
tb <- structure(list(a = 1:2), class = c("tbl_df", "tbl", "data.frame"), row.names = 1:2); print(class(as_zutable(tb)))
